describe('"'geometria',()=>{
 test('początek, pisak i zerowy krok',()=>{expect(run('np 0 np 10','2d')).toEqual({segments:[{from:[0,0,0],to:[0,10,0],color:'#16866a',width:3}],error:null})});
 test('prawo, lewo, wstecz i ułamki',()=>{near(end('pw 90 np 10 lw 90 ws 2.5'),[10,-2.5,0]);near(end('pw -90 np +3 ws .5'),[-2.5,0,0])});
